// GENERATED by scripts/sync-engine.mjs from src/engine/refresh-all.ts. Do not edit here: edit the original and run "npm run sync-engine".
// The scheduled refresh (the cron job): for EVERY environment, fetch the weather of ITS OWN location, then run the decision engine,
// so the farmer finds the alerts ready when the app is opened. Pure logic on the small Db interface: tested on a real Postgres.
//
// Rules:
// - Weather is per field (its own latitude / longitude / timezone). A field without a usable location gets no weather call.
// - At most one Open-Meteo call per field every 10 minutes (same rule as weather-sync): a recent fetch is reused ("cached").
// - If Open-Meteo fails or answers something unexpected, NOTHING is stored for that field, the old rows stay, and the decision
//   still runs (the engine says "insufficient data" for what is missing; it never guesses).
// - One field failing never stops the others.
// - Many fields: the list is rotated every hour (so the same fields are not always last), capped per run, and the run stops
//   starting new fields when its time budget is used; the fields not reached are counted and come first-in-line later.
import { toNum, type Db } from './db.ts';
import { runDecisionForField } from './run-decision.ts';

export interface WeatherAdapter {
  buildUrl(f: { latitude: number; longitude: number; timezone: string }): string;
  parse(json: unknown): { ok: true; rows: readonly object[]; rejected: number } | { ok: false; error: string };
}

export interface RefreshOptions {
  db: Db;
  weather: WeatherAdapter;
  /** GET a URL and return its JSON; must throw on a network error or a non-2xx answer */
  fetchJson: (url: string) => Promise<unknown>;
  clock?: () => number;
  minIntervalMs?: number;
  maxFields?: number;
  concurrency?: number;
  /** the run stops starting new fields after this many ms */
  budgetMs?: number;
}

export type WeatherStatus = 'ok' | 'cached' | 'skipped_no_location' | 'failed';
export type DecisionStatus = 'ok' | 'failed';

export interface FieldRefresh {
  fieldId: string;
  weather: WeatherStatus;
  decision: DecisionStatus;
  error?: string;
}

export interface RefreshSummary {
  total_fields: number;
  processed: number;
  not_reached: number;
  weather: Record<WeatherStatus, number>;
  decisions: Record<DecisionStatus, number>;
  /** up to 20 problems: which field, and what went wrong */
  failures: { field_id: string; stage: 'weather' | 'decision'; error: string }[];
}

export const DEFAULTS = { minIntervalMs: 10 * 60 * 1000, maxFields: 400, concurrency: 4, budgetMs: 100_000 } as const;
const HOUR_MS = 3_600_000;
const short = (e: unknown) => String(e instanceof Error ? e.message : e).slice(0, 200);

/** the same list, started from a different place every hour */
export function rotate<T>(items: T[], now: number): T[] {
  if (items.length === 0) return [];
  const k = Math.floor(now / HOUR_MS) % items.length;
  return [...items.slice(k), ...items.slice(0, k)];
}

async function refreshWeather(o: Required<Pick<RefreshOptions, 'minIntervalMs'>> & RefreshOptions, f: { id: string; latitude: unknown; longitude: unknown; timezone: unknown }, now: number): Promise<{ status: WeatherStatus; error?: string }> {
  const latitude = toNum(f.latitude);
  const longitude = toNum(f.longitude);
  const timezone = typeof f.timezone === 'string' ? f.timezone.trim() : '';
  if (latitude === null || longitude === null || timezone === '') return { status: 'skipped_no_location' };

  const [last] = await o.db.select<{ fetched_at: string }>('weather_observations', { columns: 'fetched_at', eq: { field_id: f.id }, order: { column: 'fetched_at', ascending: false }, limit: 1 });
  if (last && now - new Date(last.fetched_at).getTime() < o.minIntervalMs) return { status: 'cached' };

  let url: string;
  try {
    url = o.weather.buildUrl({ latitude, longitude, timezone });
  } catch (e) {
    return { status: 'skipped_no_location', error: short(e) };
  }
  let payload: unknown;
  try {
    payload = await o.fetchJson(url);
  } catch (e) {
    return { status: 'failed', error: `open_meteo_unreachable: ${short(e)}` };
  }
  const parsed = o.weather.parse(payload);
  if (!parsed.ok) return { status: 'failed', error: `open_meteo_unexpected_response: ${parsed.error}` };

  const fetchedAt = new Date(now).toISOString();
  try {
    await o.db.upsertMany('weather_observations', parsed.rows.map((r) => ({ ...r, field_id: f.id, fetched_at: fetchedAt })), 'field_id,observed_at');
  } catch (e) {
    return { status: 'failed', error: `store_failed: ${short(e)}` };
  }
  return { status: 'ok' };
}

export async function refreshAllFields(opts: RefreshOptions): Promise<RefreshSummary> {
  const clock = opts.clock ?? Date.now;
  const o = { ...opts, minIntervalMs: opts.minIntervalMs ?? DEFAULTS.minIntervalMs };
  const maxFields = opts.maxFields ?? DEFAULTS.maxFields;
  const concurrency = Math.max(1, opts.concurrency ?? DEFAULTS.concurrency);
  const startedAt = clock();
  const deadline = startedAt + (opts.budgetMs ?? DEFAULTS.budgetMs);

  const all = await opts.db.select<{ id: string; latitude: unknown; longitude: unknown; timezone: unknown }>('fields', { columns: 'id,latitude,longitude,timezone', order: { column: 'id', ascending: true } });
  const queue = rotate(all, startedAt).slice(0, maxFields);

  const summary: RefreshSummary = {
    total_fields: all.length, processed: 0, not_reached: all.length,
    weather: { ok: 0, cached: 0, skipped_no_location: 0, failed: 0 },
    decisions: { ok: 0, failed: 0 },
    failures: [],
  };
  const note = (field_id: string, stage: 'weather' | 'decision', error: string) => {
    if (summary.failures.length < 20) summary.failures.push({ field_id, stage, error });
  };

  let next = 0;
  const worker = async () => {
    while (next < queue.length && clock() < deadline) {
      const f = queue[next++];
      summary.processed++;
      const w = await refreshWeather(o, f, clock());
      summary.weather[w.status]++;
      if (w.status === 'failed') note(f.id, 'weather', w.error ?? 'failed');
      try {
        await runDecisionForField(opts.db, f.id, clock());
        summary.decisions.ok++;
      } catch (e) {
        summary.decisions.failed++;
        note(f.id, 'decision', short(e));
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(concurrency, Math.max(queue.length, 1)) }, worker));
  summary.not_reached = all.length - summary.processed;
  return summary;
}
